CREATE TABLE `project_document` (
  `project_document_id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(200) COLLATE utf8mb4_general_ci NOT NULL,
  `needs_estimate_to_move_on` bit(1) NOT NULL DEFAULT b'0',
  `needs_client_approval_to_move_on` bit(1) NOT NULL DEFAULT b'0',
  `can_expire` bit(1) NOT NULL DEFAULT b'0',
  `expire_days` smallint unsigned DEFAULT NULL,
  `next_project_document_id` int unsigned DEFAULT NULL,
  `should_be_worked` bit(1) NOT NULL DEFAULT b'0',
  `needs_to_be_contacted_by_lead_qualifier` bit(1) NOT NULL DEFAULT b'0',
  `represents_billable_sale_when_closed` bit(1) NOT NULL DEFAULT b'0',
  `declined` bit(1) NOT NULL DEFAULT b'0',
  `closed_by_default` bit(1) NOT NULL DEFAULT b'0',
  `declined_project_document_id` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT (utc_timestamp()),
  `updated_at` datetime NOT NULL DEFAULT (utc_timestamp()),
  `sort` tinyint unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`project_document_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `project_document_history` (
  `project_document_history_id` int unsigned NOT NULL AUTO_INCREMENT,
