  `description` text COLLATE utf8mb4_general_ci NOT NULL,
  `visible_to_client` bit(1) NOT NULL DEFAULT b'0',
  `created_at` datetime NOT NULL DEFAULT (utc_timestamp()),
  `updated_at` datetime NOT NULL DEFAULT (utc_timestamp()),
  PRIMARY KEY (`project_image_id`),
  KEY `idx_project_image_project` (`project_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `project_line_item` (
  `project_line_item_id` int unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int unsigned NOT NULL,
  `project_id` int unsigned NOT NULL,
  `title` varchar(200) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `work_details` text COLLATE utf8mb4_general_ci,
  `item_type_id` int unsigned DEFAULT NULL,
  `line_item_template_id` int unsigned DEFAULT NULL,
